// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        c.initialize(); // owner is address(this), never zero
    }

    function testFuzz_property(address newOwner) public {
        // Any address is admissible, including the zero address.
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: owner() is never the zero address — a transfer to
        // address(0) must revert, leaving the previous (non-zero) owner in place.
        assertTrue(c.owner() != address(0), "owner must never be the zero address");
    }
}

