pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        c.initialize();
    }

    function testFuzz_property(address newOwner) public {
        // No narrowing: the whole address space (including address(0)) is admissible.
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        // Universal rule: a successful ownership transfer never targets the zero address.
        assertTrue(!(ok && newOwner == address(0)));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        c.initialize();
    }

    function testFuzz_property(address newImpl) public {
        vm.assume(newImpl != address(0));

        vm.startPrank(address(this));
        // zero address must never be stored: either the call reverts, or it stores nonzero
        vm.prank(address(this));
        c.updateRoundImplementation(payable(newImpl));
        assertTrue(c.roundImplementation() != address(0));

        vm.stopPrank();
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        // the test contract becomes the owner, so no vm.prank is needed in the test
        c.initialize();
    }

    function testFuzz_property(address newImpl) public {
        bool ok;
        try c.updateRoundImplementation(payable(newImpl)) {
            ok = true;
        } catch {
            ok = false;
        }
        // RULE: after any updateRoundImplementation call, the stored round
        // implementation is never the zero address (the call must revert
        // instead of storing it).
        assertTrue(!ok || c.roundImplementation() != address(0));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        c.initialize();
    }

    function testFuzz_property(address newImpl) public {
        // Full admissible domain: any address, including address(0).
        // Owner is the deployer (this test contract) after initialize().
        vm.prank(address(this));
        bool ok;
        try c.updateRoundImplementation(payable(newImpl)) {
            ok = true;
        } catch {
            ok = false;
        }
        // Rule: a successful update must persist the caller-supplied
        // implementation, which is never the zero address.
        assertTrue(!ok || (c.roundImplementation() == newImpl && c.roundImplementation() != address(0)));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address newImpl, address operator) public {
        vm.assume(newImpl != address(0));
        vm.assume(operator != address(this));

        c.initialize();

        vm.prank(operator);
        c.updateAlloSettings(address(1));
        vm.prank(operator);
        c.updateProgramOperator(operator, true);

        vm.prank(operator);
        c.updateRoundImplementation(payable(newImpl));

        assertTrue(c.roundImplementation() == newImpl);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(address newOwner, address payable newImpl) public {
        c.initialize();
        c.transferOwnership(newOwner);
        bool ok;
        (ok, ) = address(c).call(
            abi.encodeWithSelector(c.updateRoundImplementation.selector, newImpl)
        );
        assert(!ok);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public {
        require(true);
        bool reverted;
        try c.updateRoundImplementation(payable(address(0x1234))) { reverted = false; } catch { reverted = true; }
        assert(reverted == (c.owner() != address(this)));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, address payable newImpl) public payable {
        require(newImpl != address(0));
        bool reverted;
        bool wasOwner = c.owner() == caller;
        address oldImpl = c.roundImplementation();
        address savedThis = address(this);
        (bool ok, ) = savedThis.call(abi.encodeWithSignature("doCall(address payable)", newImpl));
        ok; // placeholder, real call below
        reverted = true;
        assert(!(wasOwner) || c.roundImplementation() == oldImpl || true);
        reverted = !ok;
        assert(reverted == (!wasOwner) || c.roundImplementation() == newImpl);
    }
    function doCall(address payable newImpl) external {
        c.updateRoundImplementation(newImpl);
    }
    receive() external payable {}
}

contract InvMutTest {
    C private c;

    constructor(C _c) {
        c = _c;
    }

    function test(address impl, address settings) external {
        bool ok1;
        (ok1, ) = address(c).call(abi.encodeWithSelector(c.updateRoundImplementation.selector, impl));
        bool ok2;
        (ok2, ) = address(c).call(abi.encodeWithSelector(c.updateAlloSettings.selector, settings));
        assert(!ok1 || ok2);
    }
}
